local function localToDir(u,v,a)
  local sa,ca=math.sin(a.az),math.cos(a.az); local se,ce=math.sin(a.el),math.cos(a.el)
  local dx,dy,dz=sa*ce,se,ca*ce
  local rx,ry,rz=ca,0,-sa
  local ux,uy,uz=-sa*se,ce,-ca*se
  local roll=tonumber(a.roll) or 0
  if math.abs(roll)>1e-9 then
    local cr,sr=math.cos(roll),math.sin(roll)
    local r2x,r2y,r2z=rx*cr+ux*sr,ry*cr+uy*sr,rz*cr+uz*sr
    local u2x,u2y,u2z=-rx*sr+ux*cr,-ry*sr+uy*cr,-rz*sr+uz*cr
    rx,ry,rz,ux,uy,uz=r2x,r2y,r2z,u2x,u2y,u2z
  end
  local k=math.tan(a.scale)
  local qx,qy,qz=dx+u*k*rx+v*k*ux,dy+u*k*ry+v*k*uy,dz+u*k*rz+v*k*uz
  local len=math.sqrt(qx*qx+qy*qy+qz*qz); if len>1e-8 then qx,qy,qz=qx/len,qy/len,qz/len end
  return qx,qy,qz,math.atan(qx,qz),math.asin(math.max(-1,math.min(1,qy)))
end

local function anchorMoveWeight(name)
  local pinned={Pikachu=true,Charmander=true,Squirtle=true,Bulbasaur=true,Eevee=true,Jigglypuff=true,Gengar=true,Dratini=true,PokeBall=true,Mew=true,Mewtwo=true}
  if pinned[name] then return 0.55 end
  return 1.0
end

local function spreadAnchors(src)
  -- 8.1.25: keep the same traced subjects and tangent-plane drawings, but
  -- gently repel anchors that ended up reading too close together in the sky.
  -- This preserves the authored sky coverage while increasing separation of the
  -- few tight pairs the user called out.
  local work, names = {}, {}
  for name,a in pairs(src) do
    work[name] = { az=a.az, el=a.el, roll=a.roll, scale=a.scale }
    names[#names+1] = name
  end
  local pad = math.rad(17.0)
  for _=1,24 do
    local moved = false
    for i=1,#names-1 do
      local ni, ai = names[i], work[names[i]]
      for j=i+1,#names do
        local nj, aj = names[j], work[names[j]]
        local avgEl = (ai.el + aj.el) * 0.5
        local da = aj.az - ai.az
        while da > math.pi do da = da - math.pi * 2 end
        while da < -math.pi do da = da + math.pi * 2 end
        local de = aj.el - ai.el
        local sx = da * math.max(0.32, math.cos(avgEl))
        local sy = de
        local dist = math.sqrt(sx*sx + sy*sy)
        local want = (ai.scale or 0) + (aj.scale or 0) + pad
        if dist < want then
          local nx, ny
          if dist > 1e-6 then nx, ny = sx/dist, sy/dist else nx, ny = 1, 0 end
          local push = (want - dist) * 0.5
          local wi = anchorMoveWeight(ni)
          local wj = anchorMoveWeight(nj)
          local splitI = wj / (wi + wj)
          local splitJ = wi / (wi + wj)
          local cosi = math.max(0.32, math.cos(ai.el))
          local cosj = math.max(0.32, math.cos(aj.el))
          ai.az = ai.az - (nx * push * splitI) / cosi
          ai.el = math.max(math.rad(-58), math.min(math.rad(58), ai.el - ny * push * splitI))
          aj.az = aj.az + (nx * push * splitJ) / cosj
          aj.el = math.max(math.rad(-58), math.min(math.rad(58), aj.el + ny * push * splitJ))
          moved = true
        end
      end
    end
    if not moved then break end
  end
  return work
end

local SPREAD_ANCHORS = spreadAnchors(ANCHORS)
local STARS,BY_NAME
local starsBuilt=false
local ORDER={"Pikachu","Charmander","Squirtle","Bulbasaur","Eevee","Jigglypuff","Gengar","Dratini","PokeBall","Mew","Mewtwo","Poliwag","Ekans","Weedle","Pidgeotto","Rattata","Fearow","Sandshrew","Nidorino","Oddish","Vulpix","Bellsprout","Diglett","Meowth","Psyduck"}

-- 8.1.43: every traced constellation now has one exact unobstructed peak
-- luminance.  The previous 8.1.25 density-energy normalizer changed alpha per
-- subject (for example Pidgeotto/Fearow could peak at only 0.672 while several
-- older subjects saturated at 1.0), so "maximum brightness" still depended on
-- which drawing was overhead.  Keep each authored tint, but move it by the
-- minimum straight-line amount toward white (or scale it down uniformly when
-- already brighter) until Rec.709 luma is identical.  Geometry, point density,
-- landmark hierarchy and source trace colours remain available for audit.
C.PEAK_LUMA_TARGET = 0.82
local function colorLuma(r,g,b) return .2126*r + .7152*g + .0722*b end
local function equalPeakColor(col)
  local r,g,b=tonumber(col[1]) or 1,tonumber(col[2]) or 1,tonumber(col[3]) or 1
  local l=colorLuma(r,g,b); local target=C.PEAK_LUMA_TARGET
  if l < target - 1e-9 then
    local k=(target-l)/math.max(1e-9,1-l)
    r=r+(1-r)*k; g=g+(1-g)*k; b=b+(1-b)*k
  elseif l > target + 1e-9 then
    local k=target/math.max(1e-9,l)
    r=r*k; g=g*k; b=b*k
  end
  return r,g,b
end

local function addStar(name,u,v,primary)
  local a,shape=SPREAD_ANCHORS[name],TRACE[name]; if not (a and shape) then return end
  local dx,dy,dz,az,el=localToDir(u,v,a); local col=shape.color; local idx=#STARS+1
  local r,g,b=equalPeakColor(col)
  local s={ constellation=name,primary=primary and true or false,dx=dx,dy=dy,dz=dz,az=az,el=el,
    -- 8.0.4: restore the vivid traced-constellation hierarchy. 8.0.3 had
    -- allowed the dense trace stars to fall below the ordinary catalogue's
    -- typical alpha, making the drawings look washed out even at deep night.
    -- Keep geometry/trace density unchanged; only restore the authored light.
    atlasExact=shape.atlasExact==true,
    -- 8.1.17: all 25 subjects share the same balanced luminous hierarchy.
    -- .96/.73 is the exact midpoint between the original .92/.64 set and the
    -- newer atlas .1.00/.82 set the user compared against. Source-trace origin
    -- may affect sample spacing/size, never authored brightness.
    size=shape.atlasExact and (primary and 1.52 or .92) or (primary and 1.26 or .90),
    a=primary and .96 or .73,
    sourceR=col[1],sourceG=col[2],sourceB=col[3],
    r=r,g=g,b=b,
    tw=.8,tw2=.4,phase=hash(idx*3.1)*math.pi*2,phase2=hash(idx*7.7)*math.pi*2,
    twDepth=primary and .055 or .025,hideNearBuilding=false,constGain=1 }
  STARS[idx]=s; local bag=BY_NAME[name]; if not bag then bag={}; BY_NAME[name]=bag end; bag[#bag+1]=s
end
C.NAMES=ORDER; C.ANCHORS=SPREAD_ANCHORS; C.BASE_ANCHORS=ANCHORS; C.TRACE=TRACE
C.BRIGHTNESS_GAINS={}
for _,name in ipairs(ORDER) do C.BRIGHTNESS_GAINS[name]=1 end

local function normalizeBrightness()
  -- 8.1.43 supersedes 8.1.25's density-energy gain spread.  Point count is a
  -- geometry/detail property and must never lower a constellation's maximum
  -- star brightness.  Every subject therefore has exactly the same 1.0 gain;
  -- equalPeakColor above handles colour-luminance differences independently.
  for _,name in ipairs(ORDER) do
    local bag = BY_NAME[name] or {}
    C.BRIGHTNESS_GAINS[name] = 1
    for i=1,#bag do bag[i].constGain = 1 end
  end
end

-- 8.1.79: the ~8k traced-star objects are immutable but were eagerly expanded
-- during module load, even in daytime/indoors. Defer only that expansion until
-- a caller actually asks for STARS/BY_NAME/count/draw. Public tables and exact
-- constellation geometry/brightness remain identical after first access.
local function ensureStars()
  if starsBuilt then return STARS,BY_NAME end
  STARS,BY_NAME={},{}
  for _,name in ipairs(ORDER) do
    for _,p in ipairs(TRACE[name].points or {}) do addStar(name,p[1],p[2],p[3]==1) end
  end
  normalizeBrightness()
  starsBuilt=true
  rawset(C,"STARS",STARS);rawset(C,"BY_NAME",BY_NAME)
  return STARS,BY_NAME
end

C.TRACE_COUNTS={}
for _,name in ipairs(ORDER) do C.TRACE_COUNTS[name]=#(TRACE[name] and TRACE[name].points or {}) end
setmetatable(C,{__index=function(t,k)
  if k=="STARS" or k=="BY_NAME" then ensureStars();return rawget(t,k) end
end})
function C.count() ensureStars();return #STARS end

function C.appendWorld(verts,n,pushQuad,axisR,axisU,eye,radius,rotateY,vaultAng,nightVis,starFade,twinkleAlpha,t,buildingScale)
  if (nightVis or 0)<.025 then return n end
  ensureStars()
  buildingScale=math.max(0,math.min(1,tonumber(buildingScale) or 1))
  for i=1,#STARS do
    local s=STARS[i]; local fade=starFade and (starFade(s,nightVis) or nightVis) or nightVis
    if fade>=.015 then
      local dx,dy,dz=s.dx,s.dy,s.dz; if rotateY and vaultAng then dx,dy,dz=rotateY(dx,dy,dz,vaultAng) end
      local cx,cy,cz=eye[1]+dx*radius,eye[2]+dy*radius,eye[3]+dz*radius
      local tw=twinkleAlpha and twinkleAlpha(s,t or 0) or 1
      local a=math.min(1,(s.a or .34)*(s.constGain or 1)*fade*buildingScale*(.95+.05*tw))
      -- Atlas line samples are intentionally close enough to read as the same
      -- luminous continuous tracing shown in the approved mockup, not as a
      -- sparse connect-the-dots caricature.  This changes only billboard size;
      -- source geometry, anchors and point count stay exact.
      local half=s._wxStaticHalf
      if not half then
        half=s.atlasExact and math.max(.52,(s.size or .92)*.56) or math.max(.46,(s.size or .86)*.48)
        s._wxStaticHalf=half
      end
      n=pushQuad(verts,n,cx,cy,cz,half,axisR,axisU,s.r,s.g,s.b,a)
      if s.primary then n=pushQuad(verts,n,cx,cy,cz,half*.23,axisR,axisU,1,1,1,a*.28) end
    end
  end
  return n
end
return C
